<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.view');$pageTitle='Flow comercial';$pdo=db();
$owner=(int)($_GET['owner']??0);$status=(string)($_GET['status']??'open');$q=trim((string)($_GET['q']??''));$where=['1=1'];$params=[];
if(in_array($status,['open','won','lost','cancelled'],true)){$where[]='d.status=?';$params[]=$status;}if($owner>0){$where[]='d.owner_user_id=?';$params[]=$owner;}if($q!==''){$where[]='(d.title LIKE ? OR c.company_name LIKE ? OR CONCAT(p.first_name," ",COALESCE(p.last_name,"")) LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}
$sql="SELECT d.*,c.company_name,CONCAT(p.first_name,' ',COALESCE(p.last_name,'')) contact_name,u.name owner_name,s.name_es,s.name_pt,s.name_en,s.color,s.sort_order,(SELECT MIN(a.due_at) FROM activities a WHERE a.deal_id=d.id AND a.status='pending') next_activity_at,(SELECT a.subject FROM activities a WHERE a.deal_id=d.id AND a.status='pending' ORDER BY a.due_at IS NULL,a.due_at LIMIT 1) next_activity FROM deals d JOIN pipeline_stages s ON s.id=d.stage_id LEFT JOIN clients c ON c.id=d.client_id LEFT JOIN contacts p ON p.id=d.contact_id LEFT JOIN users u ON u.id=d.owner_user_id WHERE ".implode(' AND ',$where)." ORDER BY CASE WHEN d.next_action_at IS NULL THEN 1 ELSE 0 END,d.next_action_at,d.updated_at DESC";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();
$stageCount=max(1,(int)$pdo->query('SELECT COUNT(*) FROM pipeline_stages WHERE is_active=1')->fetchColumn());$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
require __DIR__.'/includes/header.php';?>
<div class="module-tabs commercial-tabs"><a href="deals.php"><?=crm_icon('kanban')?> Kanban</a><a class="active" href="deal_flow.php"><?=crm_icon('activity')?> Flow</a><?php if(has_permission('reports.view')):?><a href="reports.php"><?=crm_icon('report')?> <?=e(t('reports'))?></a><?php endif;?><?php if(has_permission('forms.view')):?><a href="lead_forms.php"><?=crm_icon('form')?> <?=e(t('lead_forms'))?></a><?php endif;?><?php if(has_permission('mailing.view')):?><a href="mailing.php"><?=crm_icon('mail')?> Emails</a><?php endif;?><?php if(has_permission('assistant.use')):?><a href="assistant.php"><?=crm_icon('assistant')?> IA</a><?php endif;?></div>
<section class="panel"><div class="panel-header"><div><h2>Seguimiento lineal de oportunidades</h2><span class="table-sub">Prioriza negocios por próxima acción, actividad pendiente, etapa y responsable.</span></div><?php if(has_permission('deals.manage')):?><a class="btn btn-primary btn-small" href="deal_form.php">+ CREAR NEGOCIO</a><?php endif;?></div><div class="panel-body"><form method="get" class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>"></label><label>Responsable<select name="owner"><option value="0">Todos</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$owner===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Estado<select name="status"><?php foreach(['open'=>'Abierto','won'=>'Ganado','lost'=>'Perdido','cancelled'=>'Cancelado']as$k=>$l):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=e(crm_deal_status_label($k))?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div></section>
<section class="panel" style="margin-top:16px"><div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay negocios con estos filtros.</div><?php else:?><table class="data-table flow-table"><thead><tr><th>Negocio</th><th>Etapa y avance</th><th>Próxima acción</th><th>Actividad pendiente</th><th>Responsable</th><th>Valor / pronóstico</th><th></th></tr></thead><tbody><?php foreach($rows as$r):$progress=min(100,max(5,round(((int)$r['sort_order']+1)/$stageCount*100)));$weighted=(float)$r['amount']*((int)$r['probability']/100);$next=$r['next_action_at']?:$r['next_activity_at'];$overdue=$next&&strtotime($next)<time()&&$r['status']==='open';?><tr><td><a class="table-title" href="deal_view.php?id=<?=$r['id']?>"><?=e($r['title'])?></a><span class="table-sub"><?=e($r['company_name']?:$r['contact_name']?:'Sin cliente')?></span></td><td><div class="flow-stage"><strong style="color:<?=e($r['color'])?>"><?=e(crm_stage_localized($r))?></strong><div class="flow-progress"><i style="width:<?=$progress?>%;background:<?=e($r['color'])?>"></i></div><small><?=$r['probability']?>%</small></div></td><td><?=e($r['next_action']?:'—')?><?php if($r['next_action_at']):?><span class="table-sub <?=$overdue?'text-danger':''?>"><?=e((new DateTimeImmutable($r['next_action_at']))->format('d/m/Y H:i'))?></span><?php endif;?></td><td><?=e($r['next_activity']?:'—')?><?php if($r['next_activity_at']):?><span class="table-sub"><?=e((new DateTimeImmutable($r['next_activity_at']))->format('d/m/Y H:i'))?></span><?php endif;?></td><td><?=e($r['owner_name']?:'Sin asignar')?></td><td><strong><?=e(format_money($r['amount'],$r['currency']))?></strong><span class="table-sub">Pronóstico: <?=e(format_money($weighted,$r['currency']))?></span></td><td><a class="btn btn-light btn-small" href="deal_view.php?id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>
<?php require __DIR__.'/includes/footer.php';?>
